-- THE HAPPY PLACE: COMPLETE FIRST-TIME DATABASE SETUP
-- Paste this entire file into Supabase > SQL Editor > New query, then click Run once.
-- Includes migrations 001, 002, and 003, plus initial settings and a draft catalogue.
-- Creates all 21 thehappyplace_ tables, functions, permissions, and the image bucket.
-- No separate migration runs or seed command are required for database setup.
-- May share a Supabase project with Grainbuds. Existing tables are preserved.
-- The transaction rolls back if any statement fails. No customer data is imported.
begin;
do $$begin if to_regclass('public.thehappyplace_products') is not null then raise exception 'Store already exists. Use individual migrations instead of setup.sql';end if;end$$;
-- The Happy Place. Creates thehappyplace_ objects alongside any existing tables.

create table public.thehappyplace_staff(user_id uuid primary key references auth.users(id),email text not null,roles text[] not null check(roles <@ array['owner','catalogue','fulfilment','marketing']::text[]));
create table public.thehappyplace_settings(id text primary key,value jsonb not null);
create table public.thehappyplace_private_settings(id text primary key,value jsonb not null);
create table public.thehappyplace_products(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,category text not null,room text not null default '',style text not null default '',material text not null default '',description text not null default '',dimensions text not null default '',care text not null default '',images jsonb not null default '[]',price_cents integer not null check(price_cents>0),active boolean not null default false,featured boolean not null default false,shipping_class text not null check(shipping_class in ('small','medium','large')),installation boolean not null default false,sample boolean not null default true,source_url text,created_at timestamptz not null default now());
create table public.thehappyplace_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references thehappyplace_products(id),label text not null,sku text not null unique,colour text not null default '',material text not null default '',size text not null default '',price_cents integer not null check(price_cents>0),stock integer check(stock>=0),lead_weeks integer not null default 0 check(lead_weeks between 0 and 104),image text,active boolean not null default true);
create table public.thehappyplace_rewards(id uuid primary key default gen_random_uuid(),title text not null,description text not null default '',points integer not null check(points>0),kind text not null check(kind in ('fixed','percent','shipping','gift')),value integer not null default 0 check(value>=0 and (kind<>'percent' or value<=100)),min_spend_cents integer not null default 0 check(min_spend_cents>=0),active boolean not null default false,starts_at timestamptz,ends_at timestamptz,limit_per_customer integer not null default 0 check(limit_per_customer>=0),product_ids uuid[] not null default '{}',gift_variant_id uuid references thehappyplace_variants(id),image text);
create table public.thehappyplace_collections(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,description text not null default '',image text not null default '',product_ids uuid[] not null default '{}',active boolean not null default false,publish_at timestamptz,ends_at timestamptz,seo_title text,seo_description text);
create table public.thehappyplace_campaigns(id uuid primary key default gen_random_uuid(),title text not null,code text not null unique,kind text not null check(kind in ('fixed','percent')),value integer not null check(value>0 and (kind<>'percent' or value<=100)),min_spend_cents integer not null default 0,max_uses integer not null default 0 check(max_uses>=0),uses integer not null default 0,starts_at timestamptz not null,ends_at timestamptz not null check(ends_at>starts_at),active boolean not null default false,product_ids uuid[] not null default '{}',subject text not null default '',message text not null default '',sent_at timestamptz);
create table public.thehappyplace_profiles(id uuid primary key references auth.users(id),email text not null,name text not null default '',created_at timestamptz not null default now());
create table public.thehappyplace_addresses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),label text not null default 'Home',address jsonb not null,created_at timestamptz not null default now());
create sequence public.thehappyplace_order_number start 1000;
create table public.thehappyplace_orders(id uuid primary key default gen_random_uuid(),number text not null unique default ('THP-'||nextval('thehappyplace_order_number')),request_id uuid not null unique,fingerprint text not null,user_id uuid references auth.users(id),customer_email text not null,address jsonb not null,billing_address jsonb,guest_token_hash text not null,guest_expires_at timestamptz not null default now()+interval '90 days',payment_status text not null default 'pending' check(payment_status in ('pending','paid','failed','expired','partially_refunded','refunded')),status text not null default 'confirmed',subtotal_cents integer not null default 0,discount_cents integer not null default 0,shipping_cents integer not null default 0,installation_cents integer not null default 0,tax_cents integer not null default 0,total_cents integer not null default 0 check(total_cents>=0),redeemed_points integer not null default 0,awarded_points integer not null default 0,refunded_cents integer not null default 0,reversed_points integer not null default 0,restored_points integer not null default 0,reward_id uuid references thehappyplace_rewards(id),campaign_id uuid references thehappyplace_campaigns(id),split_delivery boolean not null default false,delivery_method text not null default 'standard' check(delivery_method in ('standard','express')),preferred_date text not null default '',preferred_window text not null default '',utm jsonb not null default '{}',rules jsonb not null,notes text not null default '',stripe_session_id text unique,stripe_payment_intent_id text unique,reservation_released boolean not null default false,reserved_until timestamptz not null default now()+interval '35 minutes',created_at timestamptz not null default now());
create table public.thehappyplace_order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references thehappyplace_orders(id),variant_id uuid not null references thehappyplace_variants(id),product_name text not null,variant_label text not null,image text not null default '',quantity integer not null check(quantity>0),unit_price_cents integer not null check(unit_price_cents>=0),lead_weeks integer not null,stock_reserved boolean not null default false,refunded_quantity integer not null default 0 check(refunded_quantity>=0),is_gift boolean not null default false);
create table public.thehappyplace_shipments(id uuid primary key default gen_random_uuid(),order_id uuid not null references thehappyplace_orders(id),status text not null default 'preparing' check(status in ('confirmed','awaiting_stock','preparing','ready_to_schedule','scheduled','out_for_delivery','delivered','delivery_issue','cancelled')),items jsonb not null default '[]',scheduled_at timestamptz,"window" text not null default '',tracking_url text not null default '',customer_note text not null default '');
create table public.thehappyplace_order_events(id uuid primary key default gen_random_uuid(),order_id uuid not null references thehappyplace_orders(id),status text not null,message text not null,created_at timestamptz not null default now());
create table public.thehappyplace_points_entries(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),order_id uuid references thehappyplace_orders(id),delta integer not null check(delta<>0),kind text not null,note text not null default '',expires_at timestamptz,event_key text unique,created_at timestamptz not null default now());
create table public.thehappyplace_points_allocations(debit_id uuid not null references thehappyplace_points_entries(id),credit_id uuid not null references thehappyplace_points_entries(id),amount integer not null check(amount>0),primary key(debit_id,credit_id));
create index thehappyplace_points_user_idx on thehappyplace_points_entries(user_id,created_at);
create table public.thehappyplace_webhook_events(id text primary key,type text not null,created_at timestamptz not null default now());
create table public.thehappyplace_subscribers(email text primary key,name text not null default '',active boolean not null default true,token_hash text not null,created_at timestamptz not null default now());
create table public.thehappyplace_notifications(id uuid primary key default gen_random_uuid(),event_key text not null unique,recipient text not null,subject text not null,body text not null,status text not null default 'pending' check(status in ('pending','sending','sent','failed','suppressed')),attempts integer not null default 0,last_error text,locked_at timestamptz,sent_at timestamptz,campaign_id uuid references thehappyplace_campaigns(id),created_at timestamptz not null default now());
create table public.thehappyplace_audit(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id),action text not null,detail jsonb not null default '{}',created_at timestamptz not null default now());
create table public.thehappyplace_rate_limits(key text primary key,count integer not null default 1,window_at timestamptz not null default now());

create function public.thehappyplace_has_role(p_role text) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from thehappyplace_staff where user_id=auth.uid() and ('owner'=any(roles) or p_role=any(roles)));$$;
do $$declare t text;begin for t in select tablename from pg_tables where schemaname='public' and left(tablename,length('thehappyplace_'))='thehappyplace_' loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon, authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
grant usage,select on sequence thehappyplace_order_number to service_role;
grant select on thehappyplace_products,thehappyplace_variants,thehappyplace_rewards,thehappyplace_collections,thehappyplace_settings to anon,authenticated;
create policy product_read on thehappyplace_products for select using(active or thehappyplace_has_role('catalogue'));
create policy variant_read on thehappyplace_variants for select using((active and exists(select 1 from thehappyplace_products where id=product_id and active)) or thehappyplace_has_role('catalogue'));
create policy reward_read on thehappyplace_rewards for select using((active and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>now())) or thehappyplace_has_role('marketing'));
create policy collection_read on thehappyplace_collections for select using((active and (publish_at is null or publish_at<=now()) and (ends_at is null or ends_at>now())) or thehappyplace_has_role('marketing'));
create policy settings_read on thehappyplace_settings for select using(true);
grant select on thehappyplace_staff,thehappyplace_orders,thehappyplace_order_items,thehappyplace_shipments,thehappyplace_order_events,thehappyplace_points_entries,thehappyplace_profiles,thehappyplace_addresses to authenticated;
create policy staff_read on thehappyplace_staff for select using(user_id=auth.uid() or thehappyplace_has_role('owner'));
create policy orders_read on thehappyplace_orders for select using(user_id=auth.uid() or thehappyplace_has_role('fulfilment'));
create policy items_read on thehappyplace_order_items for select using(exists(select 1 from thehappyplace_orders where id=order_id and (user_id=auth.uid() or thehappyplace_has_role('fulfilment'))));
create policy shipments_read on thehappyplace_shipments for select using(exists(select 1 from thehappyplace_orders where id=order_id and (user_id=auth.uid() or thehappyplace_has_role('fulfilment'))));
create policy events_read on thehappyplace_order_events for select using(exists(select 1 from thehappyplace_orders where id=order_id and (user_id=auth.uid() or thehappyplace_has_role('fulfilment'))));
create policy points_read on thehappyplace_points_entries for select using(user_id=auth.uid() or thehappyplace_has_role('owner'));
create policy profile_read on thehappyplace_profiles for select using(id=auth.uid() or thehappyplace_has_role('owner'));
create policy addresses_read on thehappyplace_addresses for select using(user_id=auth.uid());

create function public.thehappyplace_rate_limit(p_key text,p_limit integer) returns void language plpgsql security definer set search_path=public as $$declare r thehappyplace_rate_limits;begin insert into thehappyplace_rate_limits(key) values(p_key) on conflict do nothing;select * into r from thehappyplace_rate_limits where key=p_key for update;if r.window_at<now()-interval '15 minutes' then update thehappyplace_rate_limits set count=1,window_at=now() where key=p_key;elsif r.count>=p_limit then raise exception 'Rate limit exceeded';else update thehappyplace_rate_limits set count=count+1 where key=p_key;end if;end$$;
create function public.thehappyplace_balance(p_user uuid) returns integer language sql stable security definer set search_path=public as $$select coalesce(sum(delta),0)::integer from thehappyplace_points_entries where user_id=p_user;$$;
create function public.thehappyplace_expire_points(p_user uuid default null) returns void language plpgsql security definer set search_path=public as $$declare c thehappyplace_points_entries;remaining integer;debit uuid;begin for c in select * from thehappyplace_points_entries where delta>0 and expires_at<=now() and (p_user is null or user_id=p_user) order by user_id,created_at for update loop perform pg_advisory_xact_lock(hashtextextended(c.user_id::text,0));select greatest(0,c.delta-coalesce(sum(amount),0))::integer into remaining from thehappyplace_points_allocations where credit_id=c.id;if remaining>0 then debit=gen_random_uuid();insert into thehappyplace_points_entries(id,user_id,delta,kind,note,event_key) values(debit,c.user_id,-remaining,'expiry','Unused points expired','expiry:'||c.id) on conflict(event_key) do nothing;if found then insert into thehappyplace_points_allocations values(debit,c.id,remaining);end if;end if;end loop;end$$;
create function public.thehappyplace_debit_points(p_user uuid,p_amount integer,p_order uuid,p_key text,p_note text) returns uuid language plpgsql security definer set search_path=public as $$declare debit uuid=gen_random_uuid();c record;remaining integer=p_amount;take integer;begin perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));perform thehappyplace_expire_points(p_user);if p_amount<=0 or thehappyplace_balance(p_user)<p_amount then raise exception 'Not enough points';end if;insert into thehappyplace_points_entries(id,user_id,order_id,delta,kind,event_key,note) values(debit,p_user,p_order,-p_amount,'redemption',p_key,p_note);for c in select e.id,e.delta-coalesce((select sum(amount) from thehappyplace_points_allocations where credit_id=e.id),0) as available from thehappyplace_points_entries e where e.user_id=p_user and e.delta>0 and (e.expires_at is null or e.expires_at>now()) order by e.expires_at nulls last,e.created_at loop take=least(remaining,greatest(0,c.available));if take>0 then insert into thehappyplace_points_allocations values(debit,c.id,take);remaining=remaining-take;end if;exit when remaining=0;end loop;if remaining<>0 then raise exception 'Points allocation failed';end if;return debit;end$$;
create function public.thehappyplace_credit_points(p_user uuid,p_amount integer,p_order uuid,p_key text,p_kind text,p_days integer,p_note text) returns void language plpgsql security definer set search_path=public as $$begin if p_user is null or p_amount<=0 then return;end if;perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));insert into thehappyplace_points_entries(user_id,order_id,delta,kind,event_key,expires_at,note) values(p_user,p_order,p_amount,p_kind,p_key,case when p_days>0 then now()+make_interval(days=>p_days) else null end,p_note) on conflict(event_key) do nothing;end$$;
create function public.thehappyplace_sync_profile(p_user uuid,p_email text,p_name text) returns void language plpgsql security definer set search_path=public as $$declare s jsonb;begin insert into thehappyplace_profiles(id,email,name) values(p_user,p_email,p_name) on conflict(id) do update set email=excluded.email,name=case when excluded.name<>'' then excluded.name else thehappyplace_profiles.name end;select value into s from thehappyplace_settings where id='site';if coalesce((s->>'policies_approved')::boolean,false) then perform thehappyplace_credit_points(p_user,coalesce((s->>'signup_points')::integer,0),null,'welcome:'||p_user,'welcome',coalesce((s->>'expiry_days')::integer,365),'Welcome to Happy Rewards');end if;end$$;

create function public.thehappyplace_create_order(p_user uuid,p_guest_hash text,p_fingerprint text,p_payload jsonb) returns uuid language plpgsql security definer set search_path=public as $$
declare oid uuid;old thehappyplace_orders;s jsonb;l record;v thehappyplace_variants;p thehappyplace_products;r thehappyplace_rewards;c thehappyplace_campaigns;subtotal integer=0;shipping integer=0;installation integer=0;discount integer=0;eligible integer=0;net integer;earned integer;rp integer=0;remote boolean=false;cls integer;g integer;group_total integer;group_free boolean;split boolean;gift_id uuid;group_count integer;campaign uuid;reward uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_payload->>'request_id',1));
 select * into old from thehappyplace_orders where request_id=(p_payload->>'request_id')::uuid;
 if found then if old.fingerprint<>p_fingerprint or old.user_id is distinct from p_user then raise exception 'Checkout request changed';end if;return old.id;end if;
 select value into s from thehappyplace_settings where id='site';if not coalesce((s->>'policies_approved')::boolean,false) then raise exception 'Store policies need owner review before checkout opens';end if;
 if jsonb_array_length(p_payload->'lines')<1 or jsonb_array_length(p_payload->'lines')>50 then raise exception 'Invalid basket';end if;
 if p_user is not null then perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));end if;
 oid=gen_random_uuid();split=coalesce((p_payload->>'split_delivery')::boolean,false);
 insert into thehappyplace_orders(id,request_id,fingerprint,user_id,customer_email,address,billing_address,guest_token_hash,split_delivery,delivery_method,preferred_date,preferred_window,utm,rules) values(oid,(p_payload->>'request_id')::uuid,p_fingerprint,p_user,p_payload->'address'->>'email',p_payload->'address',p_payload->'billing_address',p_guest_hash,split,coalesce(p_payload->>'delivery_method','standard'),coalesce(p_payload->>'preferred_date',''),coalesce(p_payload->>'preferred_window',''),coalesce(p_payload->'utm','{}'),s);
 for l in select (value->>'variant_id')::uuid vid,sum((value->>'quantity')::integer)::integer qty from jsonb_array_elements(p_payload->'lines') group by 1 order by 1 loop
  if l.qty<1 or l.qty>20 then raise exception 'Invalid quantity';end if;
  select * into v from thehappyplace_variants where id=l.vid for update;if not found or not v.active then raise exception 'Variant unavailable';end if;
  select * into p from thehappyplace_products where id=v.product_id;if not p.active or p.sample then raise exception 'Product requires owner verification';end if;
  if v.stock is not null then if v.stock<l.qty then raise exception 'Not enough stock';end if;update thehappyplace_variants set stock=stock-l.qty where id=v.id;end if;
  subtotal=subtotal+v.price_cents*l.qty;
  insert into thehappyplace_order_items(order_id,variant_id,product_name,variant_label,image,quantity,unit_price_cents,lead_weeks,stock_reserved) values(oid,v.id,p.name,v.label,coalesce(v.image,p.images->>0,''),l.qty,v.price_cents,v.lead_weeks,v.stock is not null);
 end loop;
 if p_payload->>'reward_id' is not null then
  if p_user is null then raise exception 'Sign in to redeem rewards';end if;
  select * into r from thehappyplace_rewards where id=(p_payload->>'reward_id')::uuid for update;
  if not found or not r.active or r.starts_at>now() or r.ends_at<=now() or subtotal<r.min_spend_cents then raise exception 'Reward not eligible';end if;
  if r.limit_per_customer>0 and (select count(*) from thehappyplace_orders where user_id=p_user and reward_id=r.id and payment_status in ('pending','paid','partially_refunded'))>=r.limit_per_customer then raise exception 'Reward limit reached';end if;
  if coalesce(p_payload->>'coupon','')<>'' then raise exception 'Rewards and discount codes cannot be combined';end if;
  rp=r.points;reward=r.id;perform thehappyplace_debit_points(p_user,rp,oid,'redeem:'||oid,r.title);
  select coalesce(sum(i.unit_price_cents*i.quantity),0)::integer into eligible from thehappyplace_order_items i join thehappyplace_variants tv on tv.id=i.variant_id where i.order_id=oid and (cardinality(r.product_ids)=0 or tv.product_id=any(r.product_ids));
  if r.kind='fixed' then discount=least(eligible,r.value);elsif r.kind='percent' then discount=floor(eligible*r.value/100.0);elsif r.kind='gift' then gift_id=r.gift_variant_id;if gift_id is null then raise exception 'Gift not configured';end if;select * into v from thehappyplace_variants where id=gift_id for update;select * into p from thehappyplace_products where id=v.product_id;if not v.active or not p.active or p.sample or v.stock=0 then raise exception 'Gift unavailable';end if;if v.stock is not null then update thehappyplace_variants set stock=stock-1 where id=v.id;end if;insert into thehappyplace_order_items(order_id,variant_id,product_name,variant_label,image,quantity,unit_price_cents,lead_weeks,stock_reserved,is_gift) values(oid,v.id,p.name,v.label,coalesce(v.image,p.images->>0,''),1,0,v.lead_weeks,v.stock is not null,true);end if;
 elsif coalesce(p_payload->>'coupon','')<>'' then
  select * into c from thehappyplace_campaigns where code=upper(p_payload->>'coupon') for update;
  if not found or not c.active or c.starts_at>now() or c.ends_at<=now() or subtotal<c.min_spend_cents or (c.max_uses>0 and c.uses>=c.max_uses) then raise exception 'Discount code not eligible';end if;
  campaign=c.id;update thehappyplace_campaigns set uses=uses+1 where id=c.id;
  select coalesce(sum(i.unit_price_cents*i.quantity),0)::integer into eligible from thehappyplace_order_items i join thehappyplace_variants tv on tv.id=i.variant_id where i.order_id=oid and (cardinality(c.product_ids)=0 or tv.product_id=any(c.product_ids));
  if c.kind='fixed' then discount=least(eligible,c.value);else discount=floor(eligible*c.value/100.0);end if;
 end if;
 remote=exists(select 1 from jsonb_array_elements_text(coalesce(s->'remote_keywords','[]')) k where position(lower(k.value) in lower(p_payload->'address'->>'street'))>0) or exists(select 1 from jsonb_array_elements_text(coalesce(s->'remote_prefixes','[]')) k where left(p_payload->'address'->>'postal',length(k.value))=k.value);
 group_count=case when split then 2 else 1 end;
 for g in 0..group_count-1 loop
  select max(case tp.shipping_class when 'large' then 2 when 'medium' then 1 else 0 end),coalesce(sum(i.quantity*i.unit_price_cents),0)::integer,bool_and((s->'free_shipping_classes') ? tp.shipping_class) into cls,group_total,group_free from thehappyplace_order_items i join thehappyplace_variants tv on tv.id=i.variant_id join thehappyplace_products tp on tp.id=tv.product_id where i.order_id=oid and (not split or (case when i.lead_weeks>0 then 1 else 0 end)=g);
  if cls is not null then if p_payload->>'delivery_method'='express' then if not coalesce((s->>'express_enabled')::boolean,false) or r.kind='shipping' then raise exception 'Express delivery not eligible';end if;shipping=shipping+coalesce((s->>'express_extra_cents')::integer,0);end if;shipping=shipping+case when group_free and group_total>=coalesce((s->>'free_shipping_min')::integer,0) then 0 else coalesce((s->>(case cls when 2 then 'shipping_large' when 1 then 'shipping_medium' else 'shipping_small' end))::integer,0) end+case when remote then coalesce((s->>'remote_surcharge')::integer,0) else 0 end;end if;
 end loop;
 if r.kind='shipping' then shipping=0;end if;
 if exists(select 1 from thehappyplace_order_items i join thehappyplace_variants tv on i.variant_id=tv.id join thehappyplace_products tp on tp.id=tv.product_id where i.order_id=oid and tp.installation) then installation=coalesce((s->>'installation_cents')::integer,0);end if;
 net=subtotal-discount;
 eligible=case when coalesce((s->>'earn_on_tax')::boolean,false) then net else floor(net*10000.0/(10000+coalesce((s->>'gst_basis_points')::integer,0))) end;
 earned=floor(eligible*coalesce((s->>'points_per_dollar')::numeric,1)/100);
 update thehappyplace_orders set subtotal_cents=subtotal,discount_cents=discount,shipping_cents=shipping,installation_cents=installation,total_cents=net+shipping+installation,tax_cents=round((net+shipping+installation)*coalesce((s->>'gst_basis_points')::numeric,0)/(10000+coalesce((s->>'gst_basis_points')::numeric,0))),redeemed_points=rp,reward_id=reward,campaign_id=campaign,rules=s||jsonb_build_object('earned_points',earned) where id=oid;
 return oid;
end$$;

create function public.thehappyplace_award_order(p_order uuid) returns void language plpgsql security definer set search_path=public as $$declare o thehappyplace_orders;n integer;begin select * into o from thehappyplace_orders where id=p_order for update;if o.user_id is null or o.payment_status not in ('paid','partially_refunded') then return;end if;if o.rules->>'award_on'='delivered' and (not exists(select 1 from thehappyplace_shipments where order_id=o.id) or exists(select 1 from thehappyplace_shipments where order_id=o.id and status<>'delivered')) then return;end if;n=coalesce((o.rules->>'earned_points')::integer,0);perform thehappyplace_credit_points(o.user_id,n,o.id,'earned:'||o.id,'purchase',coalesce((o.rules->>'expiry_days')::integer,365),o.number);update thehappyplace_orders set awarded_points=n where id=o.id;end$$;
create function public.thehappyplace_confirm_payment(p_order uuid,p_session text,p_intent text,p_event text,p_total integer) returns void language plpgsql security definer set search_path=public as $$declare o thehappyplace_orders;g integer;sid uuid;staff_email text;begin select * into o from thehappyplace_orders where id=p_order for update;if not found then raise exception 'Order missing';end if;if o.total_cents<>p_total or (o.stripe_session_id is not null and o.stripe_session_id<>p_session) then raise exception 'Payment does not match order';end if;insert into thehappyplace_webhook_events(id,type) values(p_event,'paid') on conflict do nothing;if not found then return;end if;if o.payment_status in ('paid','partially_refunded','refunded') then return;end if;if o.reservation_released then raise exception 'Reservation already released; reconciliation required';end if;update thehappyplace_orders set payment_status='paid',stripe_session_id=p_session,stripe_payment_intent_id=p_intent,status=case when exists(select 1 from thehappyplace_order_items where order_id=o.id and lead_weeks>0) then 'awaiting_stock' else 'preparing' end where id=o.id;
 for g in 0..case when o.split_delivery then 1 else 0 end loop if exists(select 1 from thehappyplace_order_items where order_id=o.id and (not o.split_delivery or (case when lead_weeks>0 then 1 else 0 end)=g)) then sid=gen_random_uuid();insert into thehappyplace_shipments(id,order_id,status,items) select sid,o.id,case when max(lead_weeks)>0 then 'awaiting_stock' else 'preparing' end,jsonb_agg(jsonb_build_object('item_id',id,'quantity',quantity)) from thehappyplace_order_items where order_id=o.id and (not o.split_delivery or (case when lead_weeks>0 then 1 else 0 end)=g);end if;end loop;
 insert into thehappyplace_order_events(order_id,status,message) values(o.id,'confirmed','Payment received. Your order is confirmed.');perform thehappyplace_award_order(o.id);
 insert into thehappyplace_notifications(event_key,recipient,subject,body) values('paid:'||o.id,o.customer_email,'Your order '||o.number||' is confirmed','Thank you for your order. Sign in to your account to see delivery updates, or use the private tracking link provided at checkout.') on conflict do nothing;
 select value->>'email' into staff_email from thehappyplace_private_settings where id='notifications';if coalesce(staff_email,'')<>'' then insert into thehappyplace_notifications(event_key,recipient,subject,body) values('staff:'||o.id,staff_email,'New order '||o.number,'A new payment is confirmed. Sign in to the admin panel to review items and delivery details.') on conflict do nothing;end if;
end$$;
create function public.thehappyplace_release_order(p_order uuid,p_reason text) returns void language plpgsql security definer set search_path=public as $$declare o thehappyplace_orders;i thehappyplace_order_items;begin select * into o from thehappyplace_orders where id=p_order for update;if not found or o.reservation_released or o.payment_status in ('paid','partially_refunded','refunded') then return;end if;if o.user_id is not null then perform pg_advisory_xact_lock(hashtextextended(o.user_id::text,0));end if;for i in select * from thehappyplace_order_items where order_id=o.id and stock_reserved order by variant_id loop update thehappyplace_variants set stock=stock+i.quantity where id=i.variant_id;end loop;perform thehappyplace_credit_points(o.user_id,o.redeemed_points,o.id,'release:'||o.id,'restoration',coalesce((o.rules->>'expiry_days')::integer,365),'Checkout reservation released');if o.campaign_id is not null then update thehappyplace_campaigns set uses=greatest(0,uses-1) where id=o.campaign_id;end if;update thehappyplace_orders set reservation_released=true,payment_status=case when p_reason='expired' then 'expired' else 'failed' end,status='cancelled' where id=o.id;end$$;
create function public.thehappyplace_apply_refund(p_order uuid,p_amount integer,p_event text) returns void language plpgsql security definer set search_path=public as $$declare o thehappyplace_orders;reversed integer;restored integer;debit uuid;credit uuid;begin select * into o from thehappyplace_orders where id=p_order for update;if not found or o.payment_status not in ('paid','partially_refunded','refunded') or p_amount>o.total_cents or p_amount<0 then raise exception 'Invalid refund';end if;insert into thehappyplace_webhook_events(id,type) values(p_event,'refund') on conflict do nothing;if not found or p_amount<=o.refunded_cents then return;end if;if o.user_id is not null then perform pg_advisory_xact_lock(hashtextextended(o.user_id::text,0));reversed=floor(o.awarded_points*p_amount::numeric/nullif(o.total_cents,0));restored=floor(o.redeemed_points*p_amount::numeric/nullif(o.total_cents,0));if reversed>o.reversed_points then debit=gen_random_uuid();insert into thehappyplace_points_entries(id,user_id,order_id,delta,kind,event_key,note) values(debit,o.user_id,o.id,-(reversed-o.reversed_points),'refund_reversal','refund-earned:'||o.id||':'||p_amount,'Refund on '||o.number);select id into credit from thehappyplace_points_entries where event_key='earned:'||o.id;if credit is not null then insert into thehappyplace_points_allocations values(debit,credit,reversed-o.reversed_points);end if;end if;perform thehappyplace_credit_points(o.user_id,restored-o.restored_points,o.id,'refund-redeem:'||o.id||':'||p_amount,'restoration',coalesce((o.rules->>'expiry_days')::integer,365),'Reward restored after refund');else reversed=0;restored=0;end if;update thehappyplace_orders set refunded_cents=p_amount,reversed_points=reversed,restored_points=restored,payment_status=case when p_amount=total_cents then 'refunded' else 'partially_refunded' end where id=o.id;insert into thehappyplace_order_events(order_id,status,message) values(o.id,'refunded','A refund of S$'||to_char(p_amount/100.0,'FM999999990.00')||' has been processed.');insert into thehappyplace_notifications(event_key,recipient,subject,body) values('refund:'||o.id||':'||p_amount,o.customer_email,'Refund update for '||o.number,'Your refund has been processed. Check your order for the updated payment and rewards history.') on conflict do nothing;end$$;

create function public.thehappyplace_save_product(p_product jsonb) returns void language plpgsql security definer set search_path=public as $$declare v jsonb;pid uuid=(p_product->>'id')::uuid;begin insert into thehappyplace_products(id,name,slug,category,room,style,material,description,dimensions,care,images,price_cents,active,featured,shipping_class,installation,sample,source_url) values(pid,p_product->>'name',p_product->>'slug',p_product->>'category',p_product->>'room',p_product->>'style',p_product->>'material',p_product->>'description',p_product->>'dimensions',p_product->>'care',p_product->'images',(p_product->>'price_cents')::integer,(p_product->>'active')::boolean,(p_product->>'featured')::boolean,p_product->>'shipping_class',(p_product->>'installation')::boolean,coalesce((p_product->>'sample')::boolean,true),p_product->>'source_url') on conflict(id) do update set name=excluded.name,slug=excluded.slug,category=excluded.category,room=excluded.room,style=excluded.style,material=excluded.material,description=excluded.description,dimensions=excluded.dimensions,care=excluded.care,images=excluded.images,price_cents=excluded.price_cents,active=excluded.active,featured=excluded.featured,shipping_class=excluded.shipping_class,installation=excluded.installation,sample=excluded.sample,source_url=excluded.source_url;
 perform 1 from thehappyplace_variants where product_id=pid order by id for update;
 update thehappyplace_variants set active=false where product_id=pid;
 for v in select value from jsonb_array_elements(p_product->'variants') loop if (v->>'product_id')::uuid<>pid or exists(select 1 from thehappyplace_variants where id=(v->>'id')::uuid and product_id<>pid) then raise exception 'Variant belongs to a different product';end if;insert into thehappyplace_variants(id,product_id,label,sku,colour,material,size,price_cents,stock,lead_weeks,image,active) values((v->>'id')::uuid,pid,v->>'label',v->>'sku',v->>'colour',v->>'material',v->>'size',(v->>'price_cents')::integer,(v->>'stock')::integer,(v->>'lead_weeks')::integer,v->>'image',true) on conflict(id) do update set label=excluded.label,sku=excluded.sku,colour=excluded.colour,material=excluded.material,size=excluded.size,price_cents=excluded.price_cents,stock=excluded.stock,lead_weeks=excluded.lead_weeks,image=excluded.image,active=true;end loop;
end$$;
create function public.thehappyplace_update_shipment(p_shipment uuid,p_data jsonb) returns void language plpgsql security definer set search_path=public as $$declare sh thehappyplace_shipments;o thehappyplace_orders;i jsonb;qty integer;other_qty integer;begin select order_id into sh.order_id from thehappyplace_shipments where id=p_shipment;select * into o from thehappyplace_orders where id=sh.order_id for update;if o.payment_status not in ('paid','partially_refunded') then raise exception 'Only paid orders can be fulfilled';end if;select * into sh from thehappyplace_shipments where id=p_shipment for update;
 if jsonb_array_length(p_data->'items')<1 then raise exception 'Shipment must contain items';end if;
 if exists(select 1 from jsonb_array_elements(p_data->'items') group by value->>'item_id' having count(*)>1) then raise exception 'Duplicate shipment item';end if;
 for i in select value from jsonb_array_elements(p_data->'items') loop select quantity into qty from thehappyplace_order_items where id=(i->>'item_id')::uuid and order_id=o.id;select coalesce(sum((j.value->>'quantity')::integer),0)::integer into other_qty from thehappyplace_shipments s cross join lateral jsonb_array_elements(s.items) j where s.order_id=o.id and s.id<>sh.id and s.status<>'cancelled' and j.value->>'item_id'=i->>'item_id';if qty is null or (i->>'quantity')::integer<1 or other_qty+(i->>'quantity')::integer>qty then raise exception 'Shipment quantities exceed ordered quantities';end if;end loop;
 if p_data->>'status' in ('scheduled','out_for_delivery','delivered') and coalesce(p_data->>'scheduled_at','')='' then raise exception 'Confirm a delivery date first';end if;
 update thehappyplace_shipments set status=p_data->>'status',items=p_data->'items',scheduled_at=nullif(p_data->>'scheduled_at','')::timestamptz,"window"=coalesce(p_data->>'window',''),tracking_url=coalesce(p_data->>'tracking_url',''),customer_note=coalesce(p_data->>'customer_note','') where id=sh.id;
 update thehappyplace_orders set status=case when not exists(select 1 from thehappyplace_shipments where order_id=o.id and status<>'delivered') and not exists(select 1 from thehappyplace_order_items oi where oi.order_id=o.id and coalesce((select sum((ji.value->>'quantity')::integer) from thehappyplace_shipments shi cross join lateral jsonb_array_elements(shi.items) ji where shi.order_id=o.id and shi.status='delivered' and ji.value->>'item_id'=oi.id::text),0)<oi.quantity) then 'delivered' else case when p_data->>'status'='delivered' then 'partially_delivered' else p_data->>'status' end end where id=o.id;
 insert into thehappyplace_order_events(order_id,status,message) values(o.id,p_data->>'status',coalesce(nullif(p_data->>'customer_note',''),'Delivery status updated.')||case when coalesce(p_data->>'scheduled_at','')<>'' then ' Delivery appointment: '||(p_data->>'scheduled_at')||' '||coalesce(p_data->>'window','') else '' end);
 perform thehappyplace_award_order(o.id);
 insert into thehappyplace_notifications(event_key,recipient,subject,body) values('shipment:'||o.id||':'||gen_random_uuid(),o.customer_email,'Delivery update for '||o.number,coalesce(nullif(p_data->>'customer_note',''),'Your delivery status has been updated.')||' Sign in to your account or use your private tracking link for details.');
end$$;
create function public.thehappyplace_adjust_points(p_user uuid,p_delta integer,p_reason text,p_actor uuid) returns void language plpgsql security definer set search_path=public as $$declare s jsonb;begin if p_delta=0 or length(trim(p_reason))<3 then raise exception 'A reason and nonzero adjustment are required';end if;perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));select value into s from thehappyplace_settings where id='site';if p_delta>0 then perform thehappyplace_credit_points(p_user,p_delta,null,'adjust:'||gen_random_uuid(),'adjustment',coalesce((s->>'expiry_days')::integer,365),p_reason);else perform thehappyplace_debit_points(p_user,-p_delta,null,'adjust:'||gen_random_uuid(),p_reason);end if;insert into thehappyplace_audit(actor_id,action,detail) values(p_actor,'points.adjust',jsonb_build_object('user_id',p_user,'delta',p_delta,'reason',p_reason));end$$;
create function public.thehappyplace_customers() returns table(id uuid,email text,name text,points integer,order_count bigint,spent_cents bigint,marketing_opt_in boolean) language sql stable security definer set search_path=public as $$select p.id,p.email,p.name,thehappyplace_balance(p.id),(select count(*) from thehappyplace_orders where user_id=p.id),(select coalesce(sum(total_cents-refunded_cents),0) from thehappyplace_orders where user_id=p.id and payment_status in ('paid','partially_refunded','refunded')),exists(select 1 from thehappyplace_subscribers where email=p.email and active) from thehappyplace_profiles p order by p.created_at desc;$$;
create function public.thehappyplace_claim_notifications() returns setof thehappyplace_notifications language sql security definer set search_path=public as $$update thehappyplace_notifications set status='sending',locked_at=now(),attempts=attempts+1 where id in (select id from thehappyplace_notifications where (status in ('pending','failed') or (status='sending' and locked_at<now()-interval '10 minutes')) and attempts<5 order by created_at limit 30 for update skip locked) returning *;$$;

-- All mutations are service-only. Routes verify identity, ownership and staff scopes.
do $$declare f record;begin for f in select oid::regprocedure signature,proname from pg_proc where pronamespace='public'::regnamespace and left(proname,length('thehappyplace_'))='thehappyplace_' loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);if f.proname='thehappyplace_has_role' then execute format('grant execute on function %s to anon,authenticated',f.signature);end if;end loop;end$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('thp-images','thp-images',true,10485760,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
-- Uploads use a scope-checked server route. Public images contain no customer data.
create policy thehappyplace_images_read on storage.objects for select using(bucket_id='thp-images');


create function public.thehappyplace_restock_return(p_item uuid,p_qty integer) returns void language plpgsql security definer set search_path=public as $$declare i thehappyplace_order_items;begin select * into i from thehappyplace_order_items where id=p_item and exists(select 1 from thehappyplace_orders where id=thehappyplace_order_items.order_id and payment_status in ('paid','partially_refunded','refunded') and not reservation_released) for update;if not found or p_qty<1 or i.refunded_quantity+p_qty>i.quantity then raise exception 'Returned quantity exceeds ordered quantity';end if;update thehappyplace_order_items set refunded_quantity=refunded_quantity+p_qty where id=i.id;if i.stock_reserved then update thehappyplace_variants set stock=stock+p_qty where id=i.variant_id;end if;end$$;
create function public.thehappyplace_set_staff(p_user uuid,p_email text,p_roles text[]) returns void language plpgsql security definer set search_path=public as $$begin perform pg_advisory_xact_lock(983478);if not ('owner'=any(p_roles)) and exists(select 1 from thehappyplace_staff where user_id=p_user and 'owner'=any(roles)) and (select count(*) from thehappyplace_staff where 'owner'=any(roles))<=1 then raise exception 'Keep at least one owner account';end if;if cardinality(p_roles)=0 then delete from thehappyplace_staff where user_id=p_user;return;end if;insert into thehappyplace_staff(user_id,email,roles) values(p_user,p_email,p_roles) on conflict(user_id) do update set email=excluded.email,roles=excluded.roles;end$$;
revoke all on function thehappyplace_restock_return(uuid,integer),thehappyplace_set_staff(uuid,text,text[]) from public,anon,authenticated;
grant execute on function thehappyplace_restock_return(uuid,integer),thehappyplace_set_staff(uuid,text,text[]) to service_role;


-- Customers can read their own orders, but never staff notes or payment secrets.
revoke select on thehappyplace_orders from authenticated;
grant select(id,number,user_id,customer_email,address,billing_address,payment_status,status,subtotal_cents,discount_cents,shipping_cents,installation_cents,tax_cents,total_cents,redeemed_points,awarded_points,refunded_cents,split_delivery,delivery_method,preferred_date,preferred_window,created_at) on thehappyplace_orders to authenticated;
create or replace function public.thehappyplace_rate_limit(p_key text,p_limit integer) returns void language plpgsql security definer set search_path=public as $$declare r thehappyplace_rate_limits;begin insert into thehappyplace_rate_limits(key) values(p_key) on conflict do nothing;if found then return;end if;select * into r from thehappyplace_rate_limits where key=p_key for update;if r.window_at<now()-interval '15 minutes' then update thehappyplace_rate_limits set count=1,window_at=now() where key=p_key;elsif r.count>=p_limit then raise exception 'Rate limit exceeded';else update thehappyplace_rate_limits set count=count+1 where key=p_key;end if;end$$;
create or replace function public.thehappyplace_expire_points(p_user uuid default null) returns void language plpgsql security definer set search_path=public as $$declare c thehappyplace_points_entries;remaining integer;debit uuid;begin for c in select * from thehappyplace_points_entries where delta>0 and expires_at<=now() and (p_user is null or user_id=p_user) order by user_id,created_at loop perform pg_advisory_xact_lock(hashtextextended(c.user_id::text,0));perform 1 from thehappyplace_points_entries where id=c.id for update;select greatest(0,c.delta-coalesce(sum(amount),0))::integer into remaining from thehappyplace_points_allocations where credit_id=c.id;if remaining>0 then debit=gen_random_uuid();insert into thehappyplace_points_entries(id,user_id,delta,kind,note,event_key) values(debit,c.user_id,-remaining,'expiry','Unused points expired','expiry:'||c.id) on conflict(event_key) do nothing;if found then insert into thehappyplace_points_allocations values(debit,c.id,remaining);end if;end if;end loop;end$$;
create or replace function public.thehappyplace_credit_points(p_user uuid,p_amount integer,p_order uuid,p_key text,p_kind text,p_days integer,p_note text) returns void language plpgsql security definer set search_path=public as $$declare credit uuid;d record;remaining integer=p_amount;take integer;begin if p_user is null or p_amount<=0 then return;end if;perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));insert into thehappyplace_points_entries(user_id,order_id,delta,kind,event_key,expires_at,note) values(p_user,p_order,p_amount,p_kind,p_key,case when p_days>0 then now()+make_interval(days=>p_days) else null end,p_note) on conflict(event_key) do nothing returning id into credit;if credit is null then return;end if;for d in select e.id,-e.delta-coalesce((select sum(amount) from thehappyplace_points_allocations where debit_id=e.id),0) as outstanding from thehappyplace_points_entries e where e.user_id=p_user and e.delta<0 order by created_at loop take=least(remaining,greatest(0,d.outstanding));if take>0 then insert into thehappyplace_points_allocations(debit_id,credit_id,amount) values(d.id,credit,take);remaining=remaining-take;end if;exit when remaining=0;end loop;end$$;
create or replace function public.thehappyplace_award_order(p_order uuid) returns void language plpgsql security definer set search_path=public as $$declare o thehappyplace_orders;n integer;reversed integer;begin select * into o from thehappyplace_orders where id=p_order for update;if o.user_id is null or o.payment_status not in ('paid','partially_refunded') or exists(select 1 from thehappyplace_points_entries where event_key='earned:'||o.id) then return;end if;if o.rules->>'award_on'='delivered' and exists(select 1 from thehappyplace_order_items i where i.order_id=o.id and coalesce((select sum((j.value->>'quantity')::integer) from thehappyplace_shipments sh cross join lateral jsonb_array_elements(sh.items) j where sh.order_id=o.id and sh.status='delivered' and j.value->>'item_id'=i.id::text),0)<i.quantity) then return;end if;n=coalesce((o.rules->>'earned_points')::integer,0);reversed=coalesce(floor(n*o.refunded_cents::numeric/nullif(o.total_cents,0)),0);perform thehappyplace_credit_points(o.user_id,n-reversed,o.id,'earned:'||o.id,'purchase',coalesce((o.rules->>'expiry_days')::integer,365),o.number);update thehappyplace_orders set awarded_points=n,reversed_points=reversed where id=o.id;end$$;
create or replace function public.thehappyplace_apply_refund(p_order uuid,p_amount integer,p_event text) returns void language plpgsql security definer set search_path=public as $$declare o thehappyplace_orders;reversed integer;restored integer;debit uuid;credit uuid;expired integer=0;available integer=0;change integer;begin select * into o from thehappyplace_orders where id=p_order for update;if not found or o.payment_status not in ('paid','partially_refunded','refunded') or p_amount>o.total_cents or p_amount<0 then raise exception 'Invalid refund';end if;insert into thehappyplace_webhook_events(id,type) values(p_event,'refund') on conflict do nothing;if not found or p_amount<=o.refunded_cents then return;end if;if o.user_id is not null then perform pg_advisory_xact_lock(hashtextextended(o.user_id::text,0));select id into credit from thehappyplace_points_entries where event_key='earned:'||o.id;if credit is not null then select coalesce(sum(a.amount),0)::integer into expired from thehappyplace_points_allocations a join thehappyplace_points_entries d on d.id=a.debit_id where a.credit_id=credit and d.kind='expiry';select greatest(0,e.delta-coalesce((select sum(amount) from thehappyplace_points_allocations where credit_id=e.id),0))::integer into available from thehappyplace_points_entries e where id=credit;end if;reversed=greatest(o.reversed_points,coalesce(floor(o.awarded_points*p_amount::numeric/nullif(o.total_cents,0)),0)-expired);restored=coalesce(floor(o.redeemed_points*p_amount::numeric/nullif(o.total_cents,0)),0);change=reversed-o.reversed_points;if change>0 then debit=gen_random_uuid();insert into thehappyplace_points_entries(id,user_id,order_id,delta,kind,event_key,note) values(debit,o.user_id,o.id,-change,'refund_reversal','refund-earned:'||o.id||':'||p_amount,'Refund on '||o.number);if credit is not null and available>0 then insert into thehappyplace_points_allocations values(debit,credit,least(change,available));end if;end if;perform thehappyplace_credit_points(o.user_id,restored-o.restored_points,o.id,'refund-redeem:'||o.id||':'||p_amount,'restoration',coalesce((o.rules->>'expiry_days')::integer,365),'Reward restored after refund');else reversed=0;restored=0;end if;update thehappyplace_orders set refunded_cents=p_amount,reversed_points=reversed,restored_points=restored,payment_status=case when p_amount=total_cents then 'refunded' else 'partially_refunded' end where id=o.id;if p_amount=o.total_cents then update thehappyplace_shipments set status='cancelled' where order_id=o.id and status<>'delivered';update thehappyplace_orders set status='cancelled' where id=o.id;end if;insert into thehappyplace_order_events(order_id,status,message) values(o.id,'refunded','A refund of S$'||to_char(p_amount/100.0,'FM999999990.00')||' has been processed.');insert into thehappyplace_notifications(event_key,recipient,subject,body) values('refund:'||o.id||':'||p_amount,o.customer_email,'Refund update for '||o.number,'Your refund has been processed. Check your order for the updated payment and rewards history.') on conflict do nothing;end$$;
create function public.thehappyplace_add_shipment(p_order uuid,p_data jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare sid uuid=gen_random_uuid();begin perform 1 from thehappyplace_orders where id=p_order for update;insert into thehappyplace_shipments(id,order_id) values(sid,p_order);perform thehappyplace_update_shipment(sid,p_data);return sid;end$$;
revoke all on function thehappyplace_add_shipment(uuid,jsonb) from public,anon,authenticated;
grant execute on function thehappyplace_add_shipment(uuid,jsonb) to service_role;

insert into public.thehappyplace_settings(id,value) values ('site','{"hero_title":"A home that\nfeels like you.","hero_subtitle":"Considered furniture. Beautiful everyday things.\nFind the pieces that make your space your own.","hero_image":"/images/hero.jpg","announcement":"Thoughtfully chosen. Made to feel like home.","announcement_starts_at":null,"announcement_ends_at":null,"points_per_dollar":1,"expiry_days":365,"signup_points":50,"award_on":"paid","shipping_small":1500,"shipping_medium":4500,"shipping_large":12000,"installation_cents":15000,"remote_surcharge":3000,"remote_prefixes":["09","63"],"remote_keywords":["tuas","sentosa"],"express_enabled":false,"express_extra_cents":3000,"free_shipping_min":30000,"free_shipping_classes":["small"],"policies_approved":false,"showroom_address":"12 Tampines North Drive 4\n#07-04 Tampines Stellar\nSingapore 529435","showroom_hours":"Tuesday to Sunday, 11am to 6pm. By appointment.","contact_email":"hello@thehappyplace.sg","about":"We believe home is where the everyday feels a little better. Explore furniture and home objects chosen for their materials, their shape, and the way they fit into your life.","shipping_policy":"Delivery fees depend on your items and address. Backordered and custom pieces have individual lead times. Our team will confirm your delivery window. These draft terms require owner review before launch.","returns_policy":"Contact our team about an incorrect, damaged, or incomplete delivery. Product-specific cancellation and return terms must be reviewed and published by the owner before launch.","privacy_policy":"We use your contact and delivery details to process your order and provide updates. Marketing emails require a separate opt-in. Contact us to request access to or removal of your data. This draft policy requires owner review before launch.","faq":"Can I view a piece before ordering?\nVisit our showroom by appointment.\n\nCan I customise my furniture?\nSend us the product and the dimensions or finish you have in mind.\n\nWhen will my order arrive?\nSee the lead time on each product. We will confirm your delivery appointment.","earn_on_tax":false,"gst_basis_points":900}'::jsonb);
